pages/product:
---
product:
    videos:
        limit: {{theme_settings.productpage_videos_count}}
    reviews:
        limit: {{theme_settings.productpage_reviews_count}}
    related_products:
        limit: {{theme_settings.productpage_related_products_count}}
    similar_by_views:
        limit: {{theme_settings.productpage_similar_by_views_count}}
---
{{inject 'productId' product.id}}

{{#partial "head"}}
    <link rel="preload" href="{{cdn 'assets/dist/theme-bundle.chunk.product.js' resourceHint='preload' as='script'}}" as="script">
{{/partial}}

{{#partial "page"}}

    {{> components/common/breadcrumbs breadcrumbs=breadcrumbs}}

    {{#each product.shipping_messages}}
        {{> components/common/alert/alert-info message}}
    {{/each}}

    {{> components/products/product-view}}

    {{{region name="product_below_content"}}}

    {{> components/products/reviews}}

    {{{region name="product_below_reviews"}}}
    {{{region name="product_below_reviews--global"}}}

    <div class="productView-productTabs">
        {{> components/products/tabs}}
    </div>

    {{> components/products/schema}}
{{/partial}}
{{> layout/base}}

components/products/product-view:
{{inject 'outOfStockDefaultMessage' (lang 'products.out_of_stock_default_message')}}

<div class="productView"
    data-event-type="product"
    data-entity-id="{{product.id}}"
    data-name="{{product.title}}"
    data-product-category="
    {{#each product.category}}
        {{#if @last}}{{this}}{{else}}{{this}}, {{/if}}
    {{/each}}"
    data-product-brand="{{product.brand.name}}"
    data-product-price="
    {{#or customer (unless settings.hide_price_from_guests)}}
        {{#if product.price.with_tax}}
            {{product.price.with_tax.value}}
        {{else}}
            {{product.price.without_tax.value}}
        {{/if}}
    {{else}}
        {{lang 'common.login_for_pricing'}}
    {{/or}}"
    data-product-variant="single-product-option">

    {{#each product.reviews.messages}}
        {{#if error}}
            {{> components/common/alert/alert-error error}}
        {{/if}}
        {{#if success}}
            {{> components/common/alert/alert-success success}}
        {{/if}}
    {{/each}}

    {{> components/eyeva/products/product-view/image-gallery}}

    <div class="_eyeva-sticky-col">
        <div class="_eyeva-sticky-box">
            <section class="productView-details product-data">
                <div class="productView-product">
                    <h1 class="productView-title" data-eyeva-product-title>{{product.title}}</h1>

                    {{#if product.main_image}}
                        <div class="_eyeva-quickview-image">
                            {{> components/common/responsive-img
                                image=product.main_image
                                class="_eyeva-quickview-img"
                                fallback_size=theme_settings.product_size
                                lazyload=theme_settings.lazyload_mode
                                default_image=theme_settings.default_image_product
                                otherAttributes="data-main-image"
                            }}
                        </div>
                    {{/if}}

                    {{#if settings.show_wishlist}}
                        {{> components/common/wishlist-dropdown}}
                    {{/if}}

                    <dl class="_eyeva-product-info-top">
                        {{#if product.brand}}
                            <dt class="is-srOnly"></dt>
                            <dd class="_brand"><a href="{{product.brand.url}}"><span>{{product.brand.name}}</span></a></dd>
                        {{/if}}

                        <dt class="sku-label"{{#unless product.sku}} style="display: none;"{{/unless}}>{{lang 'products.sku'}}</dt>
                        <dd data-product-sku>{{product.sku}}</dd>

                        {{#if product.availability}}
                            <dt class="is-srOnly">{{lang 'products.availability'}}</dt>
                            <dd>{{product.availability}}</dd>
                        {{/if}}
                    </dl>

                    <div class="_eyeva-badges">
                        {{#if product.shipping.price.value '===' 0}}
                            <div class="_badge _shipping" aria-label="{{lang 'products.shipping'}}">{{lang 'products.shipping_free'}}</div>
                        {{/if}}
                        {{#if product.condition}}
                            <div class="_badge _condition" aria-label="{{product.condition}}">{{product.condition}}</div>
                        {{/if}}
                        {{#each product.custom_fields}}
                            {{#if name '===' '__badge'}}
                                <div class="_badge _custom">{{value}}</div>
                            {{/if}}
                        {{/each}}
                    </div>

                    <div class="_group-price-bulk-rating">
                        <div class="productView-price">
                            {{#if product.call_for_price}}
                                <div class="productView-callForPrice">{{product.call_for_price}}</div>
                            {{/if}}
                            {{#or customer (unless settings.hide_price_from_guests)}}
                                {{> components/products/price price=product.price}}
                            {{else}}
                                {{> components/common/login-for-pricing}}
                            {{/or}}
                        </div>

                        {{#if settings.bulk_discount_enabled}}
                            {{#or customer (unless settings.hide_price_from_guests)}}
                                <div class="productView-info-bulkPricing">
                                    {{> components/products/bulk-discount-rates bulk_discount_rates=product.bulk_discount_rates}}
                                </div>
                            {{/or}}
                        {{/if}}

                        <div class="_regions">
                            {{{region name="product_below_price"}}}
                            {{{region name="product_below_price--global"}}}
                        </div>

                        {{#if settings.show_product_rating}}
                            {{#if product.num_reviews '>' 0}}
                                <div class="productView-rating">
                                    {{> components/products/ratings rating=product.rating}}
                                    <a href="{{product.url}}{{#if is_ajax}}#product-reviews{{/if}}" id="productReview_link" title="{{lang 'products.reviews.link_to_review_sr' total=product.num_reviews rating=product.rating}}">
                                        {{lang 'products.reviews.link_to_review_short' total=product.num_reviews rating=product.rating}}
                                    </a>
                                </div>
                            {{/if}}
                        {{/if}}
                    </div>

                    {{product.detail_messages}}
                    <dl class="productView-info">
                        {{#all product.weight theme_settings.show_product_weight}}
                            <dt class="productView-info-name">{{lang 'products.weight'}}</dt>
                            <dd class="productView-info-value" data-product-weight>{{product.weight}}</dd>
                        {{/all}}
                        {{#all product.width product.height product.depth theme_settings.show_product_dimensions}}
                            <dt class="productView-info-name">{{lang 'products.width'}}</dt>
                            <dd class="productView-info-value" data-product-width>
                                {{product.width}}
                                {{#if settings.measurements.length '==' 'Centimeters'}}
                                ({{lang 'products.measurement.metric'}})
                                {{else}}
                                ({{lang 'products.measurement.imperial'}})
                                {{/if}}
                            </dd>
                            <dt class="productView-info-name">{{lang 'products.height'}}</dt>
                            <dd class="productView-info-value" data-product-height>
                                {{product.height}}
                                {{#if settings.measurements.length '==' 'Centimeters'}}
                                ({{lang 'products.measurement.metric'}})
                                {{else}}
                                ({{lang 'products.measurement.imperial'}})
                                {{/if}}
                            </dd>
                            <dt class="productView-info-name">{{lang 'products.depth'}}</dt>
                            <dd class="productView-info-value" data-product-depth>
                                {{product.depth}}
                                {{#if settings.measurements.length '==' 'Centimeters'}}
                                ({{lang 'products.measurement.metric'}})
                                {{else}}
                                ({{lang 'products.measurement.imperial'}})
                                {{/if}}
                            </dd>
                        {{/all}}
                        {{#if product.min_purchase_quantity}}
                            <dt class="productView-info-name">{{lang 'products.min_purchase_quantity'}}</dt>
                            <dd class="productView-info-value">{{lang 'products.purchase_units' quantity=product.min_purchase_quantity}}</dd>
                        {{/if}}
                        {{#if product.max_purchase_quantity}}
                            <dt class="productView-info-name">{{lang 'products.max_purchase_quantity'}}</dt>
                            <dd class="productView-info-value">{{lang 'products.purchase_units' quantity=product.max_purchase_quantity}}</dd>
                        {{/if}}
                        {{#if product.gift_wrapping_available}}
                            <dt class="productView-info-name">{{lang 'products.gift_wrapping'}}</dt>
                            <dd class="productView-info-value">{{lang 'products.gift_wrapping_available'}}</dd>
                        {{/if}}
                        {{#if product.shipping}}
                            {{#if product.shipping.calculated}}
                                <dt class="productView-info-name">{{lang 'products.shipping'}}</dt>
                                <dd class="productView-info-value">{{lang 'products.shipping_calculated'}}</dd>
                            {{else}}
                                {{#if product.shipping.price.value '===' 0}}
                                {{else}}
                                    <dt class="productView-info-name">{{lang 'products.shipping'}}</dt>
                                    <dd class="productView-info-value">{{lang 'products.shipping_fixed' amount=product.shipping.price.formatted}}</dd>
                                {{/if}}
                            {{/if}}
                        {{/if}}
                        <dd class="productView-info-value">Sales Tax: <b>Delaware, Home To Tax Free Shopping!</b></dd>
                    </dl>
                    
                </div>

                {{{region name="product_below_shipping"}}}
                {{{region name="product_below_shipping--global"}}}
            </section>

            <section class="productView-details product-options">
                {{> components/eyeva/products/product-view/modifiers-modal/init}}

                <div class="productView-options eyeva__productView-options {{#if (getVar 'enableModifiersModal')}}_enableModifiersModal{{/if}}">
                    {{#if product.release_date }}
                        <p>{{product.release_date}}</p>
                    {{/if}}
                    <form class="form" method="post" action="{{product.cart_url}}" enctype="multipart/form-data"
                        data-cart-item-add>
                        <input type="hidden" name="action" value="add">
                        <input type="hidden" name="product_id" value="{{product.id}}"/>
                        {{#if product.cart_order_source}}
                            <input type="hidden" name="cart_order_source" value="{{product.cart_order_source}}"/>
                        {{/if}}
                        <div data-product-option-change style="display:none;">
                            {{inject 'showSwatchNames' theme_settings.show_product_swatch_names}}
                            {{> components/eyeva/products/product-view/modifiers-modal/product-options}}
                        </div>
                        <div class="form-field form-field--stock{{#unless product.stock_level}} u-hiddenVisually{{/unless}}">
                            <label class="form-label form-label--alternate">
                                {{lang 'products.current_stock'}}
                                <span data-product-stock>{{product.stock_level}}</span>
                            </label>
                        </div>

                        {{{region name="product_below_options"}}}
                        {{{region name="product_below_options--global"}}}

                        {{> components/eyeva/products/product-view/modifiers-modal/add-to-cart}}

                        {{#if product.out_of_stock}}
                            {{#if product.out_of_stock_message}}
                                {{> components/common/alert/alert-error product.out_of_stock_message}}
                            {{else}}
                                {{> components/common/alert/alert-error (lang 'products.sold_out')}}
                            {{/if}}
                        {{/if}}

                        {{{region name="product_below_add_to_cart"}}}
                        {{{region name="product_below_add_to_cart--global"}}}
                    </form>
                </div>
                {{> components/papathemes/shipping-countdown/display}}
                {{> components/papathemes/sale-countdown/display}}

                {{{region name="product_above_socials"}}}
                {{{region name="product_above_socials--global"}}}

                {{> components/common/share url=product.url className="productView-share"}}
            </section>
        </div><!-- /._eyeva-sticky-box -->
    </div><!-- /._eyeva-sticky-col -->

    <article class="productView-description">
        {{#unless quickview}}
            {{#if theme_settings.show_product_details_tabs}}
                {{> components/products/description-tabs}}
            {{else}}
                {{> components/products/description}}
            {{/if}}
        {{else}}
            {{!-- show custom fields table only in the quick-view modal --}}
            {{> components/products/description quickview=true}}
        {{/unless}}
    </article>
</div>

components/products/reviews:
{{#if settings.show_product_reviews}}
    <section class="productReviews" id="product-reviews" data-product-reviews>
        <p class="productView-collapsible-title">
            <button class="button button--plain _animation-on {{#unless theme_settings.collapse_reviews}}is-open{{/unless}}" data-collapsible="productReviews-content" type="button" aria-expanded="{{#if theme_settings.collapse_reviews}}false{{else}}true{{/if}}" aria-controls="productReviews-content">
                <span>{{lang 'products.reviews.customer_reviews'}}</span>
                <i class="icon" aria-hidden="true"><svg><use href="#icon-chevron-down-light"></use></svg></i>
            </button>
        </p>
        <div class="productView-collapsible-content _reviews {{#unless theme_settings.collapse_reviews}}is-open{{/unless}}" id="productReviews-content" aria-hidden="{{#if theme_settings.collapse_reviews}}true{{else}}false{{/if}}">
            <div class="productReview-averageRating">
                {{> components/products/ratings rating=product.rating}}
                <span>{{#if product.rating}}{{product.rating}}{{/if}}</span>
                <span>{{{lang 'products.reviews.link_to_review' total=product.num_reviews}}}</span>
            </div>

            <a href="{{product.url}}{{#if is_ajax}}#write_review{{/if}}"
                class="button button--outline productView-reviewLink"
                {{#unless is_ajax}}data-reveal-id="modal-review-form"{{/unless}}
                role="button"
            >
                {{lang 'products.reviews.new'}}
            </a>

            {{#if product.reviews.list}}
                <ul class="productReviews-list">
                    {{#each product.reviews.list}}
                        <li class="productReview">
                            <article>
                                <header>
                                    <span class="productReview-rating rating--small">
                                        {{> components/products/ratings rating=rating}}
                                        <span class="productReview-ratingNumber">{{ rating }}</span>
                                    </span>
                                    <p class="productReview-title">{{{ sanitize title }}}</p>
                                </header>
                                <p class="productReview-body">{{{ sanitize text }}}</p>
                                {{#if name}}
                                    <p class="productReview-author">
                                        {{{lang 'products.reviews.post_on_by' date=date name=(sanitize name) }}}
                                    </p>
                                {{else}}
                                    <p class="productReview-author">
                                        {{lang 'products.reviews.post_on_by' date=date name=(lang 'products.reviews.anonymous_poster')}}
                                    </p>
                                {{/if}}
                            </article>
                        </li>
                    {{/each}}
                </ul>
                {{> components/common/paginator pagination.reviews reload=true}}
            {{/if}}
        </div>
    </section>
{{/if}}

{{#if settings.show_product_reviews}}
    {{#unless is_ajax}}
        {{> components/products/modals/writeReview}}
    {{/unless}}
{{/if}}

components/products/tabs:
{{#if product.related_products}}
    <div class="section section--related">
        <div class="productView-related">
            <h2 class="section-heading">{{lang 'products.related_products'}}</h2>
            {{> components/products/carousel products=product.related_products list="Related Products"}}
        </div>
    </div>
{{/if}}

{{{region name="product_below_related"}}}
{{{region name="product_below_related--global"}}}

<div class="section section--recentlyViewed">
    {{> components/products/recentviewed display_type='carousel'}}
</div>

{{{region name="product_below_recently_viewed"}}}
{{{region name="product_below_recently_viewed--global"}}}

components/products/price:
{{!-- There are 2 code paths for generating the PDP pricing HTML determined by the following #and condition.
If a 'price_range' exists then we generate all HTML in price-range.html, otherwise it is defined here. Both code
paths generate the same HTML structure with some differences in whether that element is displayed by default (css styling).

If you are making a change here or in price-range.html, you probably want to make that change in both files. --}}

{{#and price.price_range (if theme_settings.price_ranges '==' true)}}
    {{> components/products/price-range price=price}}
{{else}}
    <div class="price-section price-section--withTax price--withTax" {{#unless price.with_tax}}style="display: none;"{{/unless}}>
        {{#if price.price_range}}
            <span class="price-starting-label">{{theme_settings.pdp-starting-price-label}}</span>
        {{/if}}
        <span class="price-label" {{#or price.non_sale_price_with_tax price.price_range}}style="display: none;"{{/or}}>
            {{theme_settings.pdp-price-label}}
        </span>
        <span class="price-now-label" {{#or (unless price.non_sale_price_with_tax) price.price_range}}style="display: none;"{{/or}}>
            {{> components/products/price-label
                label_value=theme_settings.pdp-sale-price-label
                fallback=(lang "page_builder.pdp-sale-price-label")
            }}
        </span>
        <span data-product-price-with-tax class="price price--main">{{price.with_tax.formatted}}</span>
        {{#if price.without_tax}}
            <abbr title="{{lang 'products.including_tax'}}">{{lang 'products.price_with_tax' tax_label=price.tax_label}}</abbr>
        {{/if}}
    </div>
    <div class="price-section price-section--withTax non-sale-price--withTax" {{#unless price.non_sale_price_with_tax}}style="display: none;"{{/unless}}>
        <span>
            {{> components/products/price-label
                label_value=theme_settings.pdp-non-sale-price-label
                fallback=(lang "page_builder.pdp-non-sale-price-label")
            }}
        </span>
        <span data-product-non-sale-price-with-tax class="price price--non-sale">
            {{price.non_sale_price_with_tax.formatted}}
        </span>
    </div>
    <div class="price-section price-section--withTax rrp-price--withTax" {{#unless price.rrp_with_tax}}style="display: none;"{{/unless}}>
        <span>
            {{> components/products/price-label
                label_value=theme_settings.pdp-retail-price-label
                fallback=(lang "page_builder.pdp-retail-price-label")
            }}
        </span>
        <span data-product-rrp-with-tax class="price price--rrp">
            {{price.rrp_with_tax.formatted}}
        </span>
    </div>
    <div class="price-section price-section--withoutTax price--withoutTax" {{#unless price.without_tax}}style="display: none;"{{/unless}}>
        {{#if price.price_range}}
            <span class="price-starting-label">{{theme_settings.pdp-starting-price-label}}</span>
        {{/if}}
        <span class="price-label" {{#or price.non_sale_price_without_tax price.price_range}}style="display: none;"{{/or}}>
            {{theme_settings.pdp-price-label}}
        </span>
        <span class="price-now-label" {{#or (unless price.non_sale_price_without_tax) price.price_range}}style="display: none;"{{/or}}>
            {{> components/products/price-label
                label_value=theme_settings.pdp-sale-price-label
                fallback=(lang "page_builder.pdp-sale-price-label")
            }}
        </span>
        <span data-product-price-without-tax class="price{{#if price.with_tax}} price-section--minor{{/if}} price--main">{{price.without_tax.formatted}}</span>
        {{#if price.with_tax}}
            <abbr title="{{lang 'products.excluding_tax'}}">{{lang 'products.price_without_tax' tax_label=price.tax_label}}</abbr>
        {{/if}}
    </div>
    <div class="price-section price-section--withoutTax non-sale-price--withoutTax{{#if price.with_tax}} price-section--minor{{/if}}" {{#unless price.non_sale_price_without_tax}}style="display: none;"{{/unless}}>
        <span>
            {{> components/products/price-label
                label_value=theme_settings.pdp-non-sale-price-label
                fallback=(lang "page_builder.pdp-non-sale-price-label")
            }}
        </span>
        <span data-product-non-sale-price-without-tax class="price price--non-sale">
            {{price.non_sale_price_without_tax.formatted}}
        </span>
    </div>
    <div class="price-section price-section--withoutTax rrp-price--withoutTax{{#if price.with_tax}} price-section--minor{{/if}}" {{#unless price.rrp_without_tax}}style="display: none;"{{/unless}}>
        <span>
            {{> components/products/price-label
                label_value=theme_settings.pdp-retail-price-label
                fallback=(lang "page_builder.pdp-retail-price-label")
            }}
        </span>
        <span data-product-rrp-price-without-tax class="price price--rrp">
            {{price.rrp_without_tax.formatted}}
        </span>
    </div>
    {{#if page_type '===' 'product'}}

        {{#if product.price.rrp_without_tax}}
            {{assignVar '_salePercent' (round (multiply (subtract 1 (divide product.price.without_tax.value product.price.rrp_without_tax.value)) 100))}}
        {{else if product.price.rrp_with_tax}}
            {{assignVar '_salePercent' (round (multiply (subtract 1 (divide product.price.with_tax.value product.price.rrp_with_tax.value)) 100))}}
        {{else if product.price.non_sale_price_without_tax}}
            {{assignVar '_salePercent' (round (multiply (subtract 1 (divide product.price.without_tax.value product.price.non_sale_price_without_tax.value)) 100))}}
        {{else if product.price.non_sale_price_without_tax}}
            {{assignVar '_salePercent' (round (multiply (subtract 1 (divide product.price.with_tax.value product.price.non_sale_price_with_tax.value)) 100))}}
        {{else}}
            {{assignVar '_salePercent' 0}}
        {{/if}}

        <div class="price-section price-section--salePercent" {{#if (getVar '_salePercent' '>' 0)}}{{else}}style="display: none;"{{/if}}>
            <span data-product-price-sale-percent class="price price--percent">-{{getVar '_salePercent'}}%</span>
        </div>

         <div class="price-section price-section--saving" {{#unless price.saved}}style="display: none;"{{/unless}}>
                <span>{{lang 'products.you_save_opening_text'}}</span>
                <span data-product-price-saved class="price price--saving">
                    {{price.saved.formatted}}
                </span>
                <span>{{lang 'products.you_save_closing_bracket'}}</span=>
         </div>
    {{/if}}
{{/and}}

components/eyeva/products/product-view/m:
{{!-- check if modifiers modal is enabled in theme settings --}}
{{#if theme_settings.enableModifiersModal}}
    {{assignVar 'enableModifiersModal' 1}}
{{else}}
    {{assignVar 'enableModifiersModal' 0}}
{{/if}}

{{assignVar 'txtSelectModifiers' (lang 'products.select_modifiers')}}

{{> components/papathemes/shipping-countdown/custom-field reset=true}}
{{> components/papathemes/sale-countdown/custom-field reset=true}}

{{!-- check if modifiers modal is enabled in custom fields --}}
{{#each product.custom_fields}}
    {{#if name '===' '__@modifiers_modal'}}
        {{#if value '==' '0'}}
            {{assignVar 'enableModifiersModal' 0}}
        {{else}}
            {{assignVar 'enableModifiersModal' 1}}
        {{/if}}
    {{/if}}

    {{#if name '===' '__@select_modifiers'}}
        {{assignVar 'txtSelectModifiers' value}}
    {{/if}}

    {{#if name '===' '__@stepper'}}
        {{#each (split (lowercase value) ';')}}
            {{assignVar (get 'string' (concat '__stepper_' (dashcase this))) 1}}
        {{/each}}
    {{/if}}

    {{> components/papathemes/shipping-countdown/custom-field}}
    {{> components/papathemes/sale-countdown/custom-field}}
{{/each}}

components/products/bulk-discount-rates:
{{#if bulk_discount_rates.length}}
    <div class="productView-bulkPricing">
        <p class="productView-bulkPricing-heading is-srOnly">{{lang 'products.bulk_pricing.modal_title'}}</p>
        <ul class="productView-bulkPricing-list">
            {{#each bulk_discount_rates}}
            <li>
                {{#if type '===' 'percent'}}
                    {{{lang 'products.bulk_pricing.percent' discount=discount.formatted}}}
                {{/if}}
                {{#if type '===' 'fixed'}}
                    {{{lang 'products.bulk_pricing.fixed' discount=discount.formatted}}}
                {{/if}}
                {{#if type '===' 'price'}}
                    {{{lang 'products.bulk_pricing.price' discount=discount.formatted}}}
                {{/if}}
                {{#if min '==' max}}{{{lang 'products.bulk_pricing.range_single' min=min}}}{{else}}{{{lang 'products.bulk_pricing.range' min=min max=max}}}{{/if}}
            </li>
            {{/each}}
        </ul>
    </div>
{{/if}}

components/eyeva/products/product-view/m:
{{#if (getVar 'enableModifiersModal')}}
    <button type="button" class="button button--primary eyeva__productView-openModifiersModalBtn" data-eyeva-product-option-open>{{getVar 'txtSelectModifiers'}}</button>
    <div class="eyeva__productView-productAttributes-message-wrapper" data-eyeva-product-attributes-message></div>
    <script type="application/json" data-eyeva-product-custom-fields nonce="{{nonce}}">
        {{{json product.custom_fields}}}
    </script>
    <script type="application/json" data-eyeva-product-options nonce="{{nonce}}">
        {{{json product.options}}}
    </script>
