        {{/if}}
        {{#if add_to_cart_url}}
            {{> components/products/card-qty}}
            <a href="{{add_to_cart_url}}" data-event-type="product-click" data-button-type="add-cart" class="card-figcaption-button _add-to-cart" data-papathemes-cart-item-add>
                <span class="icon"><svg aria-hidden="true"><use href="#icon-cart-shopping-fast"></use></svg></span>
                <span class="_label">{{lang 'products.add_to_cart'}}</span>
            </a>
            <span class="product-status-message aria-description--hidden">{{lang 'category.add_cart_announcement'}}</span>
        {{/if}}
        {{#if out_of_stock_message }}
            <a href="{{url}}" data-event-type="product-click" class="card-figcaption-button _outstock" data-product-id="{{id}}">
                <span class="_label">{{out_of_stock_message}}</span>
            </a>
        {{/if}}
    {{/if}}
{{/or}}
{{#unless hide_product_quick_view}}
    {{#if theme_settings.show_product_quick_view}}
        <button type="button" class="card-figcaption-button quickview" data-event-type="product-click" data-product-id="{{id}}">
            <span class="icon"><svg aria-hidden="true"><use href="#icon-magnifying-glass"></use></svg></span>
            <span class="is-srOnly">{{lang 'products.quick_view'}}</span>
        </button>
    {{/if}}
{{/unless}}
{{#if show_compare}}
    <button type="button" class="card-figcaption-button compare"
        data-compare-id="{{id}}"
        data-compare-image="{{getImage image 'productthumb_size' (cdn theme_settings.default_image_product)}}"
        data-compare-title="{{name}}" data-compare-url="{{url}}"
    >
        <span class="icon"><svg aria-hidden="true"><use href="#icon-chart-line"></use></svg></span>
        <span class="is-srOnly">{{lang 'products.quick_view'}}</span>
    </button>
{{/if}}

components/products/product-aria-label:
{{#and price.price_range (if theme_settings.price_ranges '==' true)}}
    {{#and price.price_range.min.with_tax price.price_range.max.with_tax}}
{{lang 'category.shop_by_price_range_aria'
       from=price.price_range.min.with_tax.formatted
       to=price.price_range.max.with_tax.formatted
}}
    {{else}}
{{lang 'category.shop_by_price_range_aria'
       from=price.price_range.min.without_tax.formatted
       to=price.price_range.max.without_tax.formatted
}}
    {{/and}}
{{else}}
    {{#if price.with_tax}}
        {{#if price.non_sale_price_with_tax}}
{{> components/products/price-label
    label_value=theme_settings.pdp-non-sale-price-label
    fallback=(lang "page_builder.pdp-non-sale-price-label")
}}{{price.non_sale_price_with_tax.formatted}},
{{> components/products/price-label
    label_value=theme_settings.pdp-sale-price-label
    fallback=(lang "page_builder.pdp-sale-price-label")
}}{{price.with_tax.formatted}}
        {{else}}
{{price.with_tax.formatted}}
        {{/if}}
    {{else}}
        {{#if price.non_sale_price_without_tax}}
{{> components/products/price-label
    label_value=theme_settings.pdp-non-sale-price-label
    fallback=(lang "page_builder.pdp-non-sale-price-label")
}}{{price.non_sale_price_without_tax.formatted}},
{{> components/products/price-label
    label_value=theme_settings.pdp-sale-price-label
    fallback=(lang "page_builder.pdp-sale-price-label")
}}{{price.without_tax.formatted}}
        {{else}}
{{price.without_tax.formatted}}
        {{/if}}
    {{/if}}
{{/and}}

components/eyeva/header/navigation-child:
{{#if children}}
    {{#unless id}}
        {{#if (merge this id=(concat 'page-' (incrementVar 'incrementId')))}}{{/if}}
    {{/unless}}
    <a class="navPages-childList-action _mega {{#if is_active}} activePage{{/if}}" href="{{url}}">
        <span class="navPages-label">{{name}}</span>
    </a>
    <div class="navPages-megaMenu-subMenu">
        <ul class="navPages-megaMenu-childList">
            {{#each children}}
                <li class="navPages-childList-item">
                    {{> components/eyeva/header/navigation-child-list depth=(add ../depth 1)}}
                </li>
            {{/each}}
        </ul>
    </div>
{{else}}
    <a class="navPages-childList-action _mega {{#if is_active}} activePage{{/if}}" href="{{url}}">
        <span class="navPages-label">{{name}}</span>
    </a>
{{/if}}
